112	    min-width: 0;
113	    min-height: 0;
114	    padding: 0;
115	    margin: 0;
116	    border: none;
117	    background: transparent;
118	}
119	
120	#workspaces.taskbar .taskbar-window {
121	    padding: 2px 4px;
122	    margin: 0 2px;
123	    border-radius: 5px;
124	}
125	
